/**
 * QuickPreview.tsx — Pratinjau Langsung (Live Interactive Schematic)
 *
 * Menghitung dan merender tata letak secara real-time berdasarkan:
 * - Ukuran kertas & orientasi (Portrait/Landscape/Auto-Rotate)
 * - Margin 4-sisi & batas printable area
 * - Posisi 9-titik (offset dinamis)
 * - Skala efektif (Fit Width, Fit Page, Custom, 100%)
 * - Opsi cetak (Gridlines, Headings, Black & White)
 * - Cuplikan sel lembar kerja nyata
 * - Responsif terhadap orientasi & ukuran kertas (Containment fitting tanpa kepotong)
 */

import React, { useMemo, useState, useCallback } from "react";
import { Text, Button, Tooltip, Badge } from "@fluentui/react-components";
import { ArrowSync16Regular } from "@fluentui/react-icons";
import { usePageQueue } from "@hooks/usePageQueue";
import { useAppContext } from "@store/appState";
import { getTranslations } from "@shared/i18n";
import { PAPER_SIZES } from "@shared/paperSizes";
import { calculateLayout, resolveOrientation } from "@services/layoutEngine";
import { getAllRangesDimensions } from "@services/excelService";
import { mmToPoints, toPoints } from "@shared/utils";
import "./QuickPreview.css";

/** Batasan dimensi maksimal pratinjau dalam px (Aspect-ratio containment) */
const CONTAINER_MAX_WIDTH = 260;
const CONTAINER_MAX_HEIGHT = 185;

export const QuickPreview: React.FC = () => {
  const { state } = useAppContext();
  const t = getTranslations(state.locale);
  const { selectedPageIndex, selectedPage, updatePage } = usePageQueue();
  const [isRefreshing, setIsRefreshing] = useState(false);

  // Fungsi untuk menyegarkan dimensi dan cuplikan sel dari Excel
  const handleRefresh = useCallback(async () => {
    if (!selectedPage || selectedPageIndex === null) return;
    setIsRefreshing(true);
    try {
      const dimensions = await getAllRangesDimensions([
        { sheetName: selectedPage.sheetName, address: selectedPage.address },
      ]);
      if (dimensions.length > 0) {
        updatePage(selectedPageIndex, {
          contentWidthPt: dimensions[0].widthPt,
          contentHeightPt: dimensions[0].heightPt,
        });
      }
    } catch {
      // Abaikan jika di luar Excel
    } finally {
      setIsRefreshing(false);
    }
  }, [selectedPage, selectedPageIndex, updatePage]);

  // Kalkulasi layout live berdasarkan input pengguna saat ini
  const layoutData = useMemo(() => {
    if (!selectedPage) return null;

    const paper = PAPER_SIZES[selectedPage.paper];
    if (!paper) return null;

    // Estimasi dimensi konten jika belum tersimpan
    const contentW =
      selectedPage.contentWidthPt ||
      (selectedPage.columnCount ? selectedPage.columnCount * 64 : 480);
    const contentH =
      selectedPage.contentHeightPt ||
      (selectedPage.rowCount ? selectedPage.rowCount * 20 : 360);

    // Jalankan layout engine nyata
    const layout = calculateLayout(selectedPage, contentW, contentH);
    const isLandscape = resolveOrientation(selectedPage, contentW, contentH) === "landscape";

    // Dimensi kertas dalam poin
    const paperW = mmToPoints(isLandscape ? paper.heightMm : paper.widthMm);
    const paperH = mmToPoints(isLandscape ? paper.widthMm : paper.heightMm);

    // Fitting aspek rasio: kertas selalu pas di dalam container box
    const paperAspect = paperW / paperH;
    const containerAspect = CONTAINER_MAX_WIDTH / CONTAINER_MAX_HEIGHT;

    let svgDisplayW = CONTAINER_MAX_WIDTH;
    let svgDisplayH = CONTAINER_MAX_HEIGHT;

    if (paperAspect > containerAspect) {
      // Lebih lebar (landscape)
      svgDisplayW = CONTAINER_MAX_WIDTH;
      svgDisplayH = Math.round(CONTAINER_MAX_WIDTH / paperAspect);
    } else {
      // Lebih tinggi (portrait atau rasio tinggi)
      svgDisplayH = CONTAINER_MAX_HEIGHT;
      svgDisplayW = Math.round(CONTAINER_MAX_HEIGHT * paperAspect);
    }

    // Margin pengguna dalam poin
    const userMargins = {
      top: toPoints(selectedPage.margins.top, selectedPage.margins.unit),
      bottom: toPoints(selectedPage.margins.bottom, selectedPage.margins.unit),
      left: toPoints(selectedPage.margins.left, selectedPage.margins.unit),
      right: toPoints(selectedPage.margins.right, selectedPage.margins.unit),
    };

    // Printable area boundary
    const printableBox = {
      x: userMargins.left,
      y: userMargins.top,
      w: Math.max(0, paperW - userMargins.left - userMargins.right),
      h: Math.max(0, paperH - userMargins.top - userMargins.bottom),
    };

    // Koordinat konten seleksi Excel (menggunakan sistem poin langsung)
    const contentBox = {
      x: layout.computedMargins.left,
      y: layout.computedMargins.top,
      w: layout.scaledContentWidth,
      h: layout.scaledContentHeight,
    };

    // Cek apakah konten melebihi 1 halaman (overflow batas bawah halaman pertama)
    const pageBreakY = userMargins.top + printableBox.h;
    const hasPageBreak = contentBox.y + contentBox.h > pageBreakY;

    return {
      paper,
      paperW,
      paperH,
      layout,
      svgDisplayW,
      svgDisplayH,
      userMarginBox: printableBox,
      contentBox,
      hasPageBreak,
      pageBreakY,
    };
  }, [selectedPage]);

  if (!selectedPage || !layoutData) {
    return (
      <div className="quick-preview-empty">
        <Text size={200}>{t.quickPreviewNote}</Text>
      </div>
    );
  }

  const {
    paperW,
    paperH,
    layout,
    svgDisplayW,
    svgDisplayH,
    userMarginBox,
    contentBox,
    hasPageBreak,
    pageBreakY,
  } = layoutData;
  const isBw = selectedPage.blackAndWhite;
  const showGrid = selectedPage.gridlines;
  const showHeadings = selectedPage.headings;

  // Cuplikan baris & kolom tabel untuk live visual
  const rows = Math.min(selectedPage.rowCount || 6, 8);
  const cols = Math.min(selectedPage.columnCount || 4, 6);

  // Ukuran font adaptif proporsional terhadap ukuran kertas
  const fontSize = Math.max(10, Math.min(18, paperW / 30));

  return (
    <div className="quick-preview">
      <div className="quick-preview__header">
        <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
          <Text size={200} weight="semibold">
            {t.quickPreview}
          </Text>
          <Badge appearance="tint" color="brand" size="small">
            Live
          </Badge>
        </div>
        <Tooltip content="Segarkan dimensi lembar kerja" relationship="label">
          <Button
            appearance="subtle"
            size="small"
            icon={<ArrowSync16Regular />}
            onClick={handleRefresh}
            disabled={isRefreshing}
            aria-label="Segarkan pratinjau"
          />
        </Tooltip>
      </div>

      <div className="quick-preview__canvas-wrapper">
        <svg
          className="quick-preview__canvas"
          width={svgDisplayW}
          height={svgDisplayH}
          viewBox={`0 0 ${paperW} ${paperH}`}
          aria-label="Pratinjau tata letak halaman langsung"
        >
          <defs>
            {/* Bayangan halus di sekeliling kertas */}
            <filter id="preview-paper-shadow" x="-5%" y="-5%" width="110%" height="110%">
              <feDropShadow dx="0" dy="2" stdDeviation="3" floodOpacity="0.2" />
            </filter>

            {/* Kliping ketat pada tepi batas kertas fisik agar tidak bocor keluar */}
            <clipPath id="paper-boundary-clip">
              <rect x="0" y="0" width={paperW} height={paperH} rx="2" ry="2" />
            </clipPath>
          </defs>

          {/* Kertas Putih Fisik */}
          <rect
            x="0"
            y="0"
            width={paperW}
            height={paperH}
            rx="2"
            ry="2"
            fill="#ffffff"
            stroke="#d1d5db"
            strokeWidth="1"
            filter="url(#preview-paper-shadow)"
          />

          {/* Elemen di dalam kertas (dibatasi oleh paper-boundary-clip) */}
          <g clipPath="url(#paper-boundary-clip)">
            {/* Garis Batas Margin Pengguna (Printable Area - Dashed Line) */}
            <rect
              x={userMarginBox.x}
              y={userMarginBox.y}
              width={userMarginBox.w}
              height={userMarginBox.h}
              fill="none"
              stroke={isBw ? "#9e9e9e" : "#0284c7"}
              strokeWidth="1"
              strokeDasharray="4 3"
              opacity={0.75}
            />

            {/* Kotak Konten Seleksi Excel (Posisi 9-Titik & Skala Nyata) */}
            <g transform={`translate(${contentBox.x}, ${contentBox.y})`}>
              {/* Background Konten Seleksi */}
              <rect
                x="0"
                y="0"
                width={contentBox.w}
                height={contentBox.h}
                fill={isBw ? "#f5f5f5" : "#eff6ff"}
                stroke={isBw ? "#404040" : "#2563eb"}
                strokeWidth="1.2"
                rx="2"
              />

              {/* Opsional: Headings bar (kolom A, B, C...) */}
              {showHeadings && (
                <rect
                  x="0"
                  y="0"
                  width={contentBox.w}
                  height={Math.min(contentBox.h * 0.15, 18)}
                  fill={isBw ? "#d4d4d4" : "#bfdbfe"}
                  stroke={isBw ? "#737373" : "#3b82f6"}
                  strokeWidth="0.8"
                />
              )}

              {/* Opsional: Garis Kisi (Gridlines) */}
              {showGrid && (
                <g opacity={0.65}>
                  {/* Garis Horisontal */}
                  {Array.from({ length: rows - 1 }).map((_, r) => {
                    const y = (contentBox.h / rows) * (r + 1);
                    return (
                      <line
                        key={`h-${r}`}
                        x1="0"
                        y1={y}
                        x2={contentBox.w}
                        y2={y}
                        stroke={isBw ? "#737373" : "#93c5fd"}
                        strokeWidth="0.75"
                      />
                    );
                  })}
                  {/* Garis Vertikal */}
                  {Array.from({ length: cols - 1 }).map((_, c) => {
                    const x = (contentBox.w / cols) * (c + 1);
                    return (
                      <line
                        key={`v-${c}`}
                        x1={x}
                        y1="0"
                        x2={x}
                        y2={contentBox.h}
                        stroke={isBw ? "#737373" : "#93c5fd"}
                        strokeWidth="0.75"
                      />
                    );
                  })}
                </g>
              )}

              {/* Cuplikan Teks atau Label Seleksi */}
              <text
                x={contentBox.w / 2}
                y={contentBox.h > 40 ? Math.min(30, contentBox.h / 2) : contentBox.h / 2}
                textAnchor="middle"
                dominantBaseline="middle"
                fontSize={fontSize}
                fontWeight="600"
                fill={isBw ? "#262626" : "#1d4ed8"}
              >
                {selectedPage.address}
              </text>
            </g>

            {/* Indikator Batas Halaman jika konten tumpah ke halaman berikutnya */}
            {hasPageBreak && (
              <g>
                <line
                  x1={userMarginBox.x}
                  y1={pageBreakY}
                  x2={userMarginBox.x + userMarginBox.w}
                  y2={pageBreakY}
                  stroke="#ef4444"
                  strokeWidth="1.5"
                  strokeDasharray="5 3"
                />
                <rect
                  x={userMarginBox.x + userMarginBox.w - 85}
                  y={pageBreakY - 14}
                  width="85"
                  height="13"
                  rx="2"
                  fill="#fee2e2"
                  stroke="#ef4444"
                  strokeWidth="0.8"
                />
                <text
                  x={userMarginBox.x + userMarginBox.w - 42.5}
                  y={pageBreakY - 5}
                  textAnchor="middle"
                  dominantBaseline="middle"
                  fontSize="8"
                  fontWeight="600"
                  fill="#b91c1c"
                >
                  Batas Halaman 1
                </text>
              </g>
            )}
          </g>
        </svg>
      </div>

      {/* Info footer pratinjau langsung */}
      <div className="quick-preview__info">
        <Text size={100} weight="medium">
          {t.effectiveScale}: <strong>{Math.round(layout.effectiveScale)}%</strong>
        </Text>
        <Text size={100} style={{ color: "#666" }}>
          {layout.estimatedPageCount === 1
            ? "Muat 1 Halaman"
            : `Perkiraan: ${layout.estimatedPageCount} Halaman`}
        </Text>
      </div>

      {layout.scaleWarning && (
        <div style={{ marginTop: 2 }}>
          <Badge color="warning" appearance="tint" size="small">
            {layout.scaleWarning}
          </Badge>
        </div>
      )}
    </div>
  );
};

