/**
 * appState.ts — State management sederhana dengan React Context
 *
 * Menggunakan useReducer untuk mengelola state aplikasi.
 * Tidak perlu Redux/Zustand untuk MVP — state cukup kecil.
 */

import { createContext, useContext } from "react";
import type {
  AppState,
  PageItem,
  LayoutTab,
  StatusMessage,
  SupportedLocale,
} from "@shared/types";
import { DEFAULT_LOCALE } from "@shared/constants";
import { logger } from "@services/loggerService";

// ─── State awal ───────────────────────────────────────────────────

export const initialState: AppState = {
  pages: [],
  selectedPageIndex: null,
  activeLayoutTab: "paper",
  applyToAll: false,
  isExporting: false,
  exportProgress: 0,
  statusMessage: null,
  locale: DEFAULT_LOCALE,
};

// ─── Actions ──────────────────────────────────────────────────────

export type AppAction =
  | { type: "SET_PAGES"; pages: PageItem[] }
  | { type: "ADD_PAGE"; page: PageItem }
  | { type: "UPDATE_PAGE"; index: number; page: PageItem }
  | { type: "REMOVE_PAGE"; index: number }
  | { type: "DUPLICATE_PAGE"; index: number }
  | { type: "MOVE_PAGE"; from: number; to: number }
  | { type: "SELECT_PAGE"; index: number | null }
  | { type: "SET_LAYOUT_TAB"; tab: LayoutTab }
  | { type: "SET_APPLY_TO_ALL"; applyToAll: boolean }
  | { type: "SET_EXPORTING"; isExporting: boolean; progress?: number }
  | { type: "SET_EXPORT_PROGRESS"; progress: number }
  | { type: "SET_STATUS"; message: StatusMessage | null }
  | { type: "SET_LOCALE"; locale: SupportedLocale };

// ─── Reducer ──────────────────────────────────────────────────────

export function appReducer(state: AppState, action: AppAction): AppState {
  switch (action.type) {
    case "SET_PAGES":
      return {
        ...state,
        pages: action.pages,
        selectedPageIndex:
          action.pages.length > 0
            ? Math.min(state.selectedPageIndex ?? 0, action.pages.length - 1)
            : null,
      };

    case "ADD_PAGE":
      return {
        ...state,
        pages: [...state.pages, action.page],
        selectedPageIndex: state.pages.length, // select the newly added page
      };

    case "UPDATE_PAGE": {
      const pages = [...state.pages];
      pages[action.index] = action.page;
      return { ...state, pages };
    }

    case "REMOVE_PAGE": {
      const pages = state.pages.filter((_, i) => i !== action.index);
      let selectedPageIndex = state.selectedPageIndex;
      if (selectedPageIndex !== null) {
        if (selectedPageIndex >= pages.length) {
          selectedPageIndex = pages.length > 0 ? pages.length - 1 : null;
        } else if (selectedPageIndex > action.index) {
          selectedPageIndex--;
        }
      }
      return { ...state, pages, selectedPageIndex };
    }

    case "DUPLICATE_PAGE": {
      const original = state.pages[action.index];
      if (!original) return state;
      const dup: PageItem = {
        ...original,
        id: crypto.randomUUID(),
      };
      const pages = [...state.pages];
      pages.splice(action.index + 1, 0, dup);
      return { ...state, pages, selectedPageIndex: action.index + 1 };
    }

    case "MOVE_PAGE": {
      const pages = [...state.pages];
      const [moved] = pages.splice(action.from, 1);
      pages.splice(action.to, 0, moved);
      return { ...state, pages, selectedPageIndex: action.to };
    }

    case "SELECT_PAGE":
      return { ...state, selectedPageIndex: action.index };

    case "SET_LAYOUT_TAB":
      return { ...state, activeLayoutTab: action.tab };

    case "SET_APPLY_TO_ALL":
      return { ...state, applyToAll: action.applyToAll };

    case "SET_EXPORTING":
      return {
        ...state,
        isExporting: action.isExporting,
        exportProgress: action.progress ?? 0,
      };

    case "SET_EXPORT_PROGRESS":
      return { ...state, exportProgress: action.progress };

    case "SET_STATUS":
      if (action.message) {
        logger.addEntry(
          action.message.type === "error"
            ? "error"
            : action.message.type === "warning"
              ? "warn"
              : "info",
          `[UI Status] ${action.message.text}`
        );
      }
      return { ...state, statusMessage: action.message };

    case "SET_LOCALE":
      return { ...state, locale: action.locale };

    default:
      return state;
  }
}

// ─── Context ──────────────────────────────────────────────────────

export interface AppContextValue {
  state: AppState;
  dispatch: React.Dispatch<AppAction>;
}

export const AppContext = createContext<AppContextValue | null>(null);

export function useAppContext(): AppContextValue {
  const ctx = useContext(AppContext);
  if (!ctx) {
    throw new Error("useAppContext must be used within AppContext.Provider");
  }
  return ctx;
}
