/**
 * PaperTab.tsx — Tab pengaturan ukuran kertas dan orientasi
 * Ref: PRD §4 Fitur 2A, 2B
 */

import React from "react";
import {
  Dropdown,
  Option,
  RadioGroup,
  Radio,
  Switch,
  Text,
} from "@fluentui/react-components";
import { usePageQueue } from "@hooks/usePageQueue";
import { useAppContext } from "@store/appState";
import { getTranslations } from "@shared/i18n";
import { PAPER_SIZES } from "@shared/paperSizes";
import type { Orientation } from "@shared/types";

export const PaperTab: React.FC = () => {
  const { state } = useAppContext();
  const t = getTranslations(state.locale);
  const { selectedPage, selectedPageIndex, updatePage } = usePageQueue();

  if (!selectedPage || selectedPageIndex === null) return null;

  const handlePaperChange = (_: unknown, data: { optionValue?: string }) => {
    if (data.optionValue) {
      updatePage(selectedPageIndex, { paper: data.optionValue });
    }
  };

  const handleOrientationChange = (_: unknown, data: { value: string }) => {
    updatePage(selectedPageIndex, {
      orientation: data.value as Orientation,
      autoRotate: false, // manual menang atas auto-rotate
    });
  };

  const handleAutoRotateChange = (_: unknown, data: { checked: boolean }) => {
    updatePage(selectedPageIndex, { autoRotate: data.checked });
  };

  return (
    <div className="paper-tab">
      {/* Ukuran kertas */}
      <div className="form-row form-row__full">
        <label>{t.paperSize}</label>
        <Dropdown
          value={PAPER_SIZES[selectedPage.paper]?.label ?? selectedPage.paper}
          selectedOptions={[selectedPage.paper]}
          onOptionSelect={handlePaperChange}
          size="small"
        >
          {Object.entries(PAPER_SIZES).map(([key, size]) => (
            <Option key={key} value={key} text={size.label}>
              {size.label} ({size.widthMm} × {size.heightMm} mm)
            </Option>
          ))}
        </Dropdown>
        {selectedPage.paper === "folio" && (
          <Text size={100} className="form-note">{t.folioNote}</Text>
        )}
      </div>

      {/* Orientasi */}
      <div className="form-row form-row__full">
        <label>{t.orientation}</label>
        <RadioGroup
          value={selectedPage.orientation}
          onChange={handleOrientationChange}
          layout="horizontal"
        >
          <Radio value="portrait" label={t.portrait} />
          <Radio value="landscape" label={t.landscape} />
        </RadioGroup>
      </div>

      {/* Auto-rotate */}
      <div className="form-row">
        <Switch
          checked={selectedPage.autoRotate}
          onChange={handleAutoRotateChange}
          label={t.autoRotate}
        />
      </div>
      {selectedPage.autoRotate && (
        <Text size={100} className="form-note">{t.autoRotateHint}</Text>
      )}
    </div>
  );
};
