/**
 * ErrorBoundary.tsx — Penangkap error global React
 *
 * Mencegah layar putih total saat komponen React mengalami runtime error,
 * dan menyediakan tombol untuk langsung melihat / menyalin riwayat log.
 */

import { Component, ErrorInfo, ReactNode } from "react";
import { Button, Text } from "@fluentui/react-components";
import { logger } from "@services/loggerService";
import { LogViewerButton } from "./LogViewer/LogViewerDialog";

interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null,
  };

  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    logger.addEntry(
      "error",
      `React ErrorBoundary menangkap: ${error.message}`,
      errorInfo.componentStack || error.stack
    );
  }

  public render() {
    if (this.state.hasError) {
      return (
        <div style={{ padding: 20, fontFamily: "Segoe UI, sans-serif" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <Text as="h2" size={500} weight="semibold" style={{ color: "#c42b1c" }}>
              Terjadi Kesalahan
            </Text>
            <LogViewerButton />
          </div>
          <p style={{ fontSize: 13, color: "#666", marginTop: 8 }}>
            Aplikasi mengalami kendala saat memuat antarmuka. Anda dapat melihat detail atau menyalin
            pesan error menggunakan tombol log di atas.
          </p>
          <pre
            style={{
              background: "#f8f9fa",
              border: "1px solid #e1dfdd",
              padding: 10,
              borderRadius: 4,
              fontSize: 11,
              whiteSpace: "pre-wrap",
              wordBreak: "break-word",
            }}
          >
            {this.state.error?.message}
          </pre>
          <Button
            appearance="primary"
            size="small"
            onClick={() => window.location.reload()}
            style={{ marginTop: 12 }}
          >
            Muat Ulang
          </Button>
        </div>
      );
    }

    return this.props.children;
  }
}
