import React from "react";
import { createRoot } from "react-dom/client";
import { FluentProvider, webLightTheme } from "@fluentui/react-components";
import App from "./App";
import { logger } from "@services/loggerService";
import { ErrorBoundary } from "./components/ErrorBoundary";

// Inisialisasi logger sedini mungkin
logger.init();

const rootEl = document.getElementById("root");
if (!rootEl) throw new Error("Root element #root not found");
const root = createRoot(rootEl);

function renderApp() {
  root.render(
    <React.StrictMode>
      <FluentProvider theme={webLightTheme}>
        <ErrorBoundary>
          <App />
        </ErrorBoundary>
      </FluentProvider>
    </React.StrictMode>
  );
}

// Cek apakah Office.js tersedia
if (typeof Office !== "undefined" && Office.onReady) {
  Office.onReady((info) => {
    logger.addEntry(
      "info",
      `Office.onReady selesai. Host: ${info.host || "None/Browser"}, Platform: ${info.platform || "Unknown"}`
    );
    renderApp();
  }).catch((err) => {
    logger.addEntry("error", `Gagal menginisialisasi Office.onReady: ${err?.message || err}`);
    renderApp();
  });
} else {
  logger.addEntry("warn", "Office.js tidak terdeteksi. Merender dalam mode browser standalone.");
  renderApp();
}
