/**
 * MarginTab.tsx — Tab pengaturan margin
 * Ref: PRD §4 Fitur 2D
 */

import React from "react";
import {
  Dropdown,
  Option,
  SpinButton,
  Text,
} from "@fluentui/react-components";
import { usePageQueue } from "@hooks/usePageQueue";
import { useAppContext } from "@store/appState";
import { getTranslations } from "@shared/i18n";
import { MARGIN_PRESETS } from "@shared/constants";
import { PAPER_SIZES } from "@shared/paperSizes";
import { validateMargins } from "@shared/utils";
import type { Margins, MarginUnit, MarginPreset } from "@shared/types";

export const MarginTab: React.FC = () => {
  const { state } = useAppContext();
  const t = getTranslations(state.locale);
  const { selectedPage, selectedPageIndex, updatePage } = usePageQueue();

  if (!selectedPage || selectedPageIndex === null) return null;

  const paper = PAPER_SIZES[selectedPage.paper];
  const validationError = paper
    ? validateMargins(selectedPage.margins, paper.widthMm, paper.heightMm)
    : null;

  const handleMarginChange = (side: keyof Margins, value: number | null) => {
    if (value === null) return;
    updatePage(selectedPageIndex, {
      margins: { ...selectedPage.margins, [side]: value },
    });
  };

  const handleUnitChange = (_: unknown, data: { optionValue?: string }) => {
    if (data.optionValue) {
      updatePage(selectedPageIndex, {
        margins: { ...selectedPage.margins, unit: data.optionValue as MarginUnit },
      });
    }
  };

  const handlePresetChange = (_: unknown, data: { optionValue?: string }) => {
    if (data.optionValue) {
      const preset = MARGIN_PRESETS[data.optionValue as MarginPreset];
      if (preset) {
        updatePage(selectedPageIndex, { margins: { ...preset } });
      }
    }
  };

  return (
    <div className="margin-tab">
      {/* Preset */}
      <div className="form-row form-row__full">
        <label>{t.marginPreset}</label>
        <Dropdown size="small" placeholder={t.marginPreset} onOptionSelect={handlePresetChange}>
          <Option value="narrow">{t.presetNarrow}</Option>
          <Option value="medium">{t.presetMedium}</Option>
          <Option value="normal">{t.presetNormal}</Option>
          <Option value="wide">{t.presetWide}</Option>
          <Option value="zero">{t.presetZero}</Option>
        </Dropdown>
      </div>

      {/* Satuan */}
      <div className="form-row">
        <label>{t.marginUnit}</label>
        <Dropdown
          size="small"
          value={selectedPage.margins.unit}
          selectedOptions={[selectedPage.margins.unit]}
          onOptionSelect={handleUnitChange}
          style={{ minWidth: 80 }}
        >
          <Option value="cm">cm</Option>
          <Option value="mm">mm</Option>
          <Option value="in">inci</Option>
        </Dropdown>
      </div>

      {/* Input margin 4 sisi */}
      <div className="form-grid-2">
        <div>
          <label>{t.marginTop}</label>
          <SpinButton
            size="small"
            value={selectedPage.margins.top}
            min={0}
            max={100}
            step={0.1}
            onChange={(_e, data) => handleMarginChange("top", data.value ?? null)}
          />
        </div>
        <div>
          <label>{t.marginBottom}</label>
          <SpinButton
            size="small"
            value={selectedPage.margins.bottom}
            min={0}
            max={100}
            step={0.1}
            onChange={(_e, data) => handleMarginChange("bottom", data.value ?? null)}
          />
        </div>
        <div>
          <label>{t.marginLeft}</label>
          <SpinButton
            size="small"
            value={selectedPage.margins.left}
            min={0}
            max={100}
            step={0.1}
            onChange={(_e, data) => handleMarginChange("left", data.value ?? null)}
          />
        </div>
        <div>
          <label>{t.marginRight}</label>
          <SpinButton
            size="small"
            value={selectedPage.margins.right}
            min={0}
            max={100}
            step={0.1}
            onChange={(_e, data) => handleMarginChange("right", data.value ?? null)}
          />
        </div>
      </div>

      {/* Validasi */}
      {validationError && (
        <Text size={100} style={{ color: "var(--colorPaletteRedForeground1)" }}>
          {validationError}
        </Text>
      )}
    </div>
  );
};
