/**
 * pdfExportService.ts — Orkestrator ekspor PDF
 *
 * Mengelola alur lengkap: validasi → staging → ekspor → unduh → bersihkan.
 * Ref: PRD §4.2, §4.3, §4.4
 */

import type { PageItem, LayoutCalculation } from "@shared/types";
import { calculateLayout } from "./layoutEngine";
import {
  createAllStagingSheets,
  prepareForExport,
  cleanupStaging,
} from "./stagingService";
import {
  exportPdf,
  saveSheetVisibility,
  getActiveSheetInfo,
  type SheetVisibilityState,
} from "./excelService";
import { logger } from "./loggerService";

export interface ExportOptions {
  /** Callback progres (0–100) */
  onProgress?: (percent: number, message: string) => void;
  /** Callback saat ingin dicek apakah dibatalkan */
  isCancelled?: () => boolean;
}

export interface ExportResult {
  success: boolean;
  pdfData?: Uint8Array;
  error?: string;
  cancelled?: boolean;
}

/**
 * Jalankan alur ekspor PDF lengkap.
 *
 * Alur:
 * 1. Simpan state workbook (visibilitas, sheet aktif, seleksi)
 * 2. Hitung layout untuk semua halaman
 * 3. Buat staging sheet untuk semua halaman
 * 4. Sembunyikan sheet non-staging
 * 5. Ekspor PDF (getFileAsync)
 * 6. Bersihkan staging dan pulihkan state (WAJIB di finally)
 */
export async function runExport(
  pages: PageItem[],
  contentDimensions: Array<{ widthPt: number; heightPt: number }>,
  options: ExportOptions = {}
): Promise<ExportResult> {
  const { onProgress, isCancelled } = options;

  let stagingNames: string[] = [];
  let originalVisibility: Array<{ name: string; visibility: Excel.SheetVisibility | "Visible" | "Hidden" | "VeryHidden" }> = [];
  let savedVisibility: SheetVisibilityState[] | null = null;
  let activeSheetInfo: { sheetId: string; selection: string } | null = null;

  try {
    // 0. Cek pembatalan
    if (isCancelled?.()) return { success: false, cancelled: true };

    // 1. Simpan state
    logger.addEntry("info", "[runExport] Menyimpan state workbook...");
    onProgress?.(5, "Menyimpan state workbook...");
    savedVisibility = await saveSheetVisibility();
    activeSheetInfo = await getActiveSheetInfo();
    logger.addEntry("info", `[runExport] State tersimpan. Total sheet: ${savedVisibility.length}`);

    // 2. Hitung layout untuk semua halaman
    logger.addEntry("info", "[runExport] Menghitung tata letak halaman...");
    onProgress?.(10, "Menghitung tata letak...");
    const layouts: LayoutCalculation[] = pages.map((page, i) =>
      calculateLayout(page, contentDimensions[i].widthPt, contentDimensions[i].heightPt)
    );

    if (isCancelled?.()) return { success: false, cancelled: true };

    // 3. Buat staging sheets
    logger.addEntry("info", `[runExport] Membuat ${pages.length} staging sheet...`);
    onProgress?.(15, "Membuat sheet staging...");
    stagingNames = await createAllStagingSheets(pages, layouts, (current, total) => {
      const progress = 15 + (current / total) * 40;
      onProgress?.(progress, `Membuat halaman ${current}/${total}...`);
    });
    logger.addEntry("info", `[runExport] Staging sheet berhasil dibuat: ${stagingNames.join(", ")}`);

    if (isCancelled?.()) return { success: false, cancelled: true };

    // 4. Sembunyikan sheet non-staging
    logger.addEntry("info", "[runExport] Menyembunyikan sheet non-staging...");
    onProgress?.(60, "Menyiapkan ekspor...");
    originalVisibility = await prepareForExport(stagingNames);

    // 5. Ekspor PDF
    logger.addEntry("info", "[runExport] Memanggil exportPdf() via Office.getFileAsync...");
    onProgress?.(70, "Mengekspor PDF...");
    const pdfData = await exportPdf();
    logger.addEntry("info", `[runExport] exportPdf() berhasil! Ukuran data: ${pdfData.byteLength} bytes.`);
    onProgress?.(95, "PDF berhasil dibuat!");

    return { success: true, pdfData };
  } catch (error) {
    logger.logError("pdfExportService.runExport", error);
    const message = error instanceof Error ? error.message : "Gagal mengekspor PDF.";
    return { success: false, error: message };
  } finally {
    // 6. WAJIB: bersihkan staging dan pulihkan state
    try {
      logger.addEntry("info", "[runExport.finally] Memulai pembersihan staging sheet...");
      onProgress?.(97, "Membersihkan...");

      if (originalVisibility.length > 0) {
        await cleanupStaging(stagingNames, originalVisibility);
      } else if (stagingNames.length > 0) {
        // Jika prepareForExport belum sempat jalan tapi staging sudah dibuat
        const visToRestore = savedVisibility || (await saveSheetVisibility());
        await cleanupStaging(stagingNames, visToRestore);
      }
      logger.addEntry("info", "[runExport.finally] Pembersihan staging selesai.");

      // Pulihkan sheet aktif
      if (activeSheetInfo) {
        await Excel.run(async (context) => {
          try {
            const sheets = context.workbook.worksheets;
            sheets.load("items/id");
            await context.sync();

            const activeSheet = sheets.items.find((s) => s.id === activeSheetInfo!.sheetId);
            if (activeSheet) {
              activeSheet.activate();
              await context.sync();
            }
          } catch {
            // Abaikan
          }
        });
      }

      onProgress?.(100, "Selesai.");
    } catch {
      // Cleanup gagal — ini kasus terburuk
      console.error("Gagal membersihkan staging sheets. Cek manual.");
    }
  }
}

/**
 * Unduh PDF sebagai file.
 * Mencoba <a download> terlebih dahulu; jika gagal, buka di tab baru.
 */
export function downloadPdf(data: Uint8Array, filename: string = "print-studio-export.pdf"): void {
  logger.addEntry("info", `[downloadPdf] Menyiapkan unduhan PDF (${data.byteLength} bytes)...`);
  const blob = new Blob([data as unknown as BlobPart], { type: "application/pdf" });
  const url = URL.createObjectURL(blob);

  try {
    const a = document.createElement("a");
    a.href = url;
    a.download = filename;
    a.style.display = "none";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    logger.addEntry("info", `[downloadPdf] Unduhan PDF berhasil dipicu via <a download="${filename}">.`);
  } catch (err) {
    logger.logError("downloadPdf.anchorClick", err);
    // Fallback: buka di tab/jendela baru
    try {
      logger.addEntry("info", "[downloadPdf] Mencoba fallback via Office.context.ui.openBrowserWindow...");
      Office.context.ui.openBrowserWindow(url);
    } catch (fallbackErr) {
      logger.logError("downloadPdf.openBrowserWindow", fallbackErr);
      window.open(url, "_blank");
    }
  }

  // Bersihkan blob URL setelah delay
  setTimeout(() => URL.revokeObjectURL(url), 60000);
}

import { storePdfForPreview } from "./pdfStorage";

let activeDialog: Office.Dialog | null = null;

/**
 * Buka dialog pratinjau PDF penuh atau penampil cetak menggunakan Office Dialog API.
 * Solusi resmi Office Add-in untuk menghindari masalah blob URL pada openBrowserWindow di Windows Shell.
 * @param data Byte array data PDF
 * @param autoPrint Apakah mode cetak langsung
 */
export async function openPdfDialog(data: Uint8Array, autoPrint: boolean = false): Promise<void> {
  logger.addEntry("info", `[openPdfDialog] Menyiapkan dialog penampil PDF (${data.byteLength} bytes, autoPrint: ${autoPrint})...`);

  // Simpan data PDF ke storage lokal (IndexedDB + localStorage)
  await storePdfForPreview(data);

  if (autoPrint) {
    sessionStorage.setItem("eps_auto_print", "true");
  } else {
    sessionStorage.removeItem("eps_auto_print");
  }

  // Jika di lingkungan Office dengan dukungan displayDialogAsync
  if (typeof Office !== "undefined" && Office.context?.ui?.displayDialogAsync) {
    return new Promise<void>((resolve, reject) => {
      // Jika dialog sebelumnya masih terbuka, tutup terlebih dahulu
      if (activeDialog) {
        try {
          activeDialog.close();
        } catch {
          // Abaikan jika dialog sudah tertutup
        }
        activeDialog = null;
      }

      // Pastikan URL absolute ke dialog.html
      const dialogUrl = new URL("dialog.html", window.location.href).href;
      logger.addEntry("info", `[openPdfDialog] Membuka Office.context.ui.displayDialogAsync: ${dialogUrl}`);

      Office.context.ui.displayDialogAsync(
        dialogUrl,
        { height: 90, width: 85, promptBeforeOpen: false },
        (asyncResult) => {
          if (asyncResult.status === Office.AsyncResultStatus.Failed) {
            logger.logError("openPdfDialog.displayDialogAsync", asyncResult.error);
            // Fallback aman: unduh PDF agar pengguna tetap mendapatkan file
            downloadPdf(data, "print-studio-dokumen.pdf");
            reject(new Error(asyncResult.error?.message || "Gagal membuka jendela dialog pratinjau"));
            return;
          }

          logger.addEntry("info", "[openPdfDialog] Jendela dialog Office berhasil ditampilkan!");
          activeDialog = asyncResult.value;

          activeDialog.addEventHandler(Office.EventType.DialogMessageReceived, (arg: { message: string; origin: string | undefined } | { error: number }) => {
            try {
              if ("message" in arg) {
                const msg = JSON.parse(arg.message);
                if (msg.action === "CLOSE_DIALOG") {
                  logger.addEntry("info", "[openPdfDialog] Menerima sinyal CLOSE_DIALOG dari child dialog.");
                  activeDialog?.close();
                  activeDialog = null;
                }
              }
            } catch (e) {
              logger.logError("openPdfDialog.messageHandler", e);
            }
          });

          activeDialog.addEventHandler(Office.EventType.DialogEventReceived, (arg: unknown) => {
            logger.addEntry("info", `[openPdfDialog] Dialog ditutup oleh pengguna: ${JSON.stringify(arg)}`);
            activeDialog = null;
          });

          resolve();
        }
      );
    });
  }

  // Fallback di luar Office (misal unit test atau browser standar tanpa Office.js)
  logger.addEntry("info", "[openPdfDialog] Office Dialog API tidak tersedia, fallback unduh PDF.");
  downloadPdf(data, "print-studio-dokumen.pdf");
}

/**
 * Buka PDF di jendela browser/penampil PDF sistem agar pengguna dapat langsung mencetak.
 * Ref: PRD §4.3 "Buka untuk Cetak"
 */
export async function openPdfInViewer(data: Uint8Array): Promise<void> {
  return openPdfDialog(data, true);
}
