/**
 * i18n/index.ts — Modul lokalisasi
 *
 * Bahasa default: Indonesia. Bahasa yang didukung: id, en.
 * Preferensi bahasa disimpan di localStorage.
 */

import type { SupportedLocale } from "../types";
import { DEFAULT_LOCALE } from "../constants";
import id from "./id";
import en from "./en";

/** Tipe string translations generik berdasarkan struktur id.ts */
export type Translations = {
  [K in keyof typeof id]: (typeof id)[K] extends (...args: infer A) => any
    ? (...args: A) => string
    : string;
};

const locales: Record<SupportedLocale, Translations> = { id, en };

/**
 * Ambil objek terjemahan untuk locale tertentu.
 */
export function getTranslations(locale: SupportedLocale = DEFAULT_LOCALE): Translations {
  return locales[locale] ?? locales[DEFAULT_LOCALE];
}

/**
 * Simpan preferensi bahasa ke localStorage (dibungkus try/catch).
 */
export function saveLocalePreference(locale: SupportedLocale): void {
  try {
    localStorage.setItem("printStudio_locale", locale);
  } catch {
    // localStorage mungkin tidak tersedia di beberapa webview
  }
}

/**
 * Baca preferensi bahasa dari localStorage.
 */
export function loadLocalePreference(): SupportedLocale {
  try {
    const stored = localStorage.getItem("printStudio_locale");
    if (stored === "id" || stored === "en") return stored;
  } catch {
    // ignore
  }
  return DEFAULT_LOCALE;
}
