/**
 * ActionBar.tsx — Bar aksi bawah (Ekspor PDF, Buka untuk Cetak, Pratinjau Penuh)
 * Ref: PRD §4.2, §4.3, §5
 */

import React from "react";
import {
  Button,
  ProgressBar,
  Text,
} from "@fluentui/react-components";
import {
  DocumentPdf24Regular,
  Print24Regular,
  Eye24Regular,
} from "@fluentui/react-icons";
import { useExportPdf } from "@hooks/useExportPdf";
import { useAppContext } from "@store/appState";
import { getTranslations } from "@shared/i18n";
import "./ActionBar.css";

export const ActionBar: React.FC = () => {
  const { state } = useAppContext();
  const t = getTranslations(state.locale);
  const {
    isExporting,
    exportProgress,
    startExport,
    startPrint,
    openFullPreview,
    cancelExport,
  } = useExportPdf();

  const hasPages = state.pages.length > 0;
  const hasInvalidPages = state.pages.some((p) => !p.isValid);

  return (
    <div className="action-bar">
      {/* Progress bar saat ekspor */}
      {isExporting && (
        <div className="action-bar__progress">
          <ProgressBar value={exportProgress / 100} thickness="medium" />
          <Text size={100}>{Math.round(exportProgress)}%</Text>
        </div>
      )}

      {/* Tombol pratinjau PDF penuh (P1) */}
      <Button
        appearance="subtle"
        icon={<Eye24Regular />}
        onClick={openFullPreview}
        disabled={!hasPages || isExporting || hasInvalidPages}
        style={{ width: "100%", marginBottom: 6 }}
      >
        {t.fullPreview}
      </Button>

      {/* Tombol aksi utama */}
      <div className="action-bar__buttons">
        {isExporting ? (
          <Button
            appearance="secondary"
            onClick={cancelExport}
            style={{ width: "100%" }}
          >
            {t.cancel}
          </Button>
        ) : (
          <>
            <Button
              appearance="primary"
              icon={<DocumentPdf24Regular />}
              onClick={startExport}
              disabled={!hasPages || hasInvalidPages}
              style={{ flex: 2 }}
            >
              {t.exportPdf}
            </Button>

            <Button
              appearance="secondary"
              icon={<Print24Regular />}
              onClick={startPrint}
              disabled={!hasPages || hasInvalidPages}
              style={{ flex: 1 }}
            >
              {t.openForPrint}
            </Button>
          </>
        )}
      </div>
    </div>
  );
};
