/**
 * MiscTab.tsx — Tab pengaturan tambahan (garis kisi, judul, hitam-putih)
 * Ref: PRD §4 Fitur 2F
 */

import React from "react";
import { Switch } from "@fluentui/react-components";
import { usePageQueue } from "@hooks/usePageQueue";
import { useAppContext } from "@store/appState";
import { getTranslations } from "@shared/i18n";

export const MiscTab: React.FC = () => {
  const { state } = useAppContext();
  const t = getTranslations(state.locale);
  const { selectedPage, selectedPageIndex, updatePage } = usePageQueue();

  if (!selectedPage || selectedPageIndex === null) return null;

  return (
    <div className="misc-tab">
      <Switch
        checked={selectedPage.gridlines}
        onChange={(_e, data) =>
          updatePage(selectedPageIndex, { gridlines: data.checked })
        }
        label={t.printGridlines}
      />

      <Switch
        checked={selectedPage.headings}
        onChange={(_e, data) =>
          updatePage(selectedPageIndex, { headings: data.checked })
        }
        label={t.printHeadings}
      />

      <Switch
        checked={selectedPage.blackAndWhite}
        onChange={(_e, data) =>
          updatePage(selectedPageIndex, { blackAndWhite: data.checked })
        }
        label={t.blackAndWhite}
      />
    </div>
  );
};
