/**
 * layoutEngine.ts — Mesin kalkulasi tata letak
 *
 * Menghitung skala efektif, offset margin untuk 9-titik,
 * dan perkiraan jumlah halaman cetak.
 * Ref: PRD §4 Fitur 2C, 2E
 */

import type {
  PageItem,
  Position,
  LayoutCalculation,
  ScaleMode,
} from "@shared/types";
import { PAPER_SIZES } from "@shared/paperSizes";
import { SCALE_WARNING_THRESHOLD } from "@shared/constants";
import { mmToPoints, toPoints } from "@shared/utils";

/**
 * Hitung tata letak lengkap untuk satu halaman.
 *
 * @param page - Data halaman dari antrean
 * @param contentWidthPt - Lebar konten dalam poin (dari range.width)
 * @param contentHeightPt - Tinggi konten dalam poin (dari range.height)
 */
export function calculateLayout(
  page: PageItem,
  contentWidthPt: number,
  contentHeightPt: number
): LayoutCalculation {
  const paper = PAPER_SIZES[page.paper];
  if (!paper) {
    throw new Error(`Ukuran kertas tidak dikenal: ${page.paper}`);
  }

  // Tentukan orientasi efektif
  const isLandscape = resolveOrientation(page, contentWidthPt, contentHeightPt) === "landscape";

  // Dimensi kertas dalam poin (tukar jika landscape)
  const paperW = mmToPoints(isLandscape ? paper.heightMm : paper.widthMm);
  const paperH = mmToPoints(isLandscape ? paper.widthMm : paper.heightMm);

  // Margin minimum pengguna dalam poin
  const userMargins = {
    top: toPoints(page.margins.top, page.margins.unit),
    bottom: toPoints(page.margins.bottom, page.margins.unit),
    left: toPoints(page.margins.left, page.margins.unit),
    right: toPoints(page.margins.right, page.margins.unit),
  };

  // Area cetak (printable area)
  const printableWidth = paperW - userMargins.left - userMargins.right;
  const printableHeight = paperH - userMargins.top - userMargins.bottom;

  // Hitung skala efektif
  const effectiveScale = calculateEffectiveScale(
    page.scaleMode,
    page.customScale,
    contentWidthPt,
    contentHeightPt,
    printableWidth,
    printableHeight
  );

  // Ukuran konten setelah skala
  const scaledW = contentWidthPt * (effectiveScale / 100);
  const scaledH = contentHeightPt * (effectiveScale / 100);

  // Hitung offset margin untuk posisi 9-titik
  const computedMargins = calculatePositionMargins(
    page.position,
    userMargins,
    scaledW,
    scaledH,
    printableWidth,
    printableHeight
  );

  // Perkiraan jumlah halaman cetak
  const estimatedPageCount = estimatePageCount(
    page.scaleMode,
    scaledW,
    scaledH,
    printableWidth,
    printableHeight
  );

  // Peringatan skala
  const scaleWarning =
    effectiveScale < SCALE_WARNING_THRESHOLD
      ? `Skala efektif ${Math.round(effectiveScale)}% — teks mungkin terlalu kecil`
      : undefined;

  return {
    effectiveScale,
    scaledContentWidth: scaledW,
    scaledContentHeight: scaledH,
    printableWidth,
    printableHeight,
    computedMargins,
    estimatedPageCount,
    scaleWarning,
  };
}

// ─── Sub-kalkulasi ────────────────────────────────────────────────

/**
 * Tentukan orientasi efektif (manual menang atas auto-rotate).
 */
export function resolveOrientation(
  page: PageItem,
  contentWidthPt: number,
  contentHeightPt: number
): "portrait" | "landscape" {
  if (!page.autoRotate) {
    return page.orientation;
  }
  // Auto-rotate: landscape jika konten lebih lebar dari tinggi
  return contentWidthPt > contentHeightPt ? "landscape" : "portrait";
}

/**
 * Hitung skala efektif berdasarkan mode.
 */
export function calculateEffectiveScale(
  mode: ScaleMode,
  customScale: number,
  contentW: number,
  contentH: number,
  printableW: number,
  printableH: number
): number {
  switch (mode) {
    case "fitWidth":
      return (printableW / contentW) * 100;

    case "fitPage": {
      const scaleW = printableW / contentW;
      const scaleH = printableH / contentH;
      return Math.min(scaleW, scaleH) * 100;
    }

    case "custom":
      return customScale;

    case "actual":
      return 100;

    default:
      return 100;
  }
}

/**
 * Hitung margin offset untuk posisi 9-titik.
 *
 * Strategi (PRD §4 Fitur 2C):
 * 1. Hitung sisa ruang horizontal dan vertikal.
 * 2. Terjemahkan posisi menjadi offset margin.
 * 3. Posisi "tengah" boleh memakai centerHorizontally/centerVertically.
 */
export function calculatePositionMargins(
  position: Position,
  userMargins: { top: number; bottom: number; left: number; right: number },
  scaledW: number,
  scaledH: number,
  printableW: number,
  printableH: number
): { top: number; bottom: number; left: number; right: number } {
  // Sisa ruang
  const extraH = Math.max(0, printableW - scaledW);
  const extraV = Math.max(0, printableH - scaledH);

  let marginLeft = userMargins.left;
  let marginRight = userMargins.right;
  let marginTop = userMargins.top;
  let marginBottom = userMargins.bottom;

  // Horizontal
  switch (position.horizontal) {
    case "left":
      // Konten menempel margin kiri; tambahkan sisa ke margin kanan
      marginRight += extraH;
      break;
    case "center":
      // Sisa dibagi dua
      marginLeft += extraH / 2;
      marginRight += extraH / 2;
      break;
    case "right":
      // Konten menempel margin kanan; tambahkan sisa ke margin kiri
      marginLeft += extraH;
      break;
  }

  // Vertical
  switch (position.vertical) {
    case "top":
      marginBottom += extraV;
      break;
    case "center":
      marginTop += extraV / 2;
      marginBottom += extraV / 2;
      break;
    case "bottom":
      marginTop += extraV;
      break;
  }

  return {
    top: marginTop,
    bottom: marginBottom,
    left: marginLeft,
    right: marginRight,
  };
}

/**
 * Perkirakan jumlah halaman cetak.
 */
export function estimatePageCount(
  mode: ScaleMode,
  scaledW: number,
  scaledH: number,
  printableW: number,
  printableH: number
): number {
  if (mode === "fitPage") return 1;

  const pagesWide = Math.ceil(scaledW / printableW);
  const pagesTall = Math.ceil(scaledH / printableH);
  return pagesWide * pagesTall;
}
