/**
 * PageQueue.tsx — Komponen antrean halaman
 *
 * Menampilkan daftar halaman, tombol tambah, dan kontrol per item.
 * Ref: PRD §4 Fitur 1, §5
 */

import React from "react";
import {
  Button,
  Text,
  Badge,
} from "@fluentui/react-components";
import { Add24Regular } from "@fluentui/react-icons";
import { usePageQueue } from "@hooks/usePageQueue";
import { useAppContext } from "@store/appState";
import { getTranslations } from "@shared/i18n";
import { PageQueueItem } from "./PageQueueItem";
import "./PageQueue.css";

export const PageQueue: React.FC = () => {
  const { state } = useAppContext();
  const t = getTranslations(state.locale);
  const {
    pages,
    selectedPageIndex,
    addFromSelection,
    removePage,
    duplicatePage,
    moveUp,
    moveDown,
    selectPage,
  } = usePageQueue();

  return (
    <div className="page-queue">
      {/* Tombol tambah */}
      <Button
        appearance="primary"
        icon={<Add24Regular />}
        onClick={addFromSelection}
        disabled={state.isExporting}
        style={{ width: "100%" }}
      >
        {t.addSelection}
      </Button>

      {/* Header antrean */}
      <div className="queue-header">
        <Text size={300} weight="semibold">
          {t.queue}
        </Text>
        <Badge appearance="filled" color="informative" size="small">
          {t.queuePages(pages.length)}
        </Badge>
      </div>

      {/* Daftar halaman */}
      {pages.length === 0 ? (
        <Text size={200} className="queue-empty">
          {t.queueEmpty}
        </Text>
      ) : (
        <div className="queue-list" role="listbox" aria-label={t.queue}>
          {pages.map((page, index) => (
            <PageQueueItem
              key={page.id}
              page={page}
              index={index}
              isSelected={index === selectedPageIndex}
              isFirst={index === 0}
              isLast={index === pages.length - 1}
              disabled={state.isExporting}
              onSelect={() => selectPage(index)}
              onMoveUp={() => moveUp(index)}
              onMoveDown={() => moveDown(index)}
              onDuplicate={() => duplicatePage(index)}
              onRemove={() => removePage(index)}
            />
          ))}
        </div>
      )}
    </div>
  );
};
